from taf.gnb.oam.coam.cu.schemas.base import SchemaField, SchemaObject


class Alarm(SchemaObject):
    uuid = SchemaField(name="uuid")
    severity = SchemaField(name="severity")
    alarm_id = SchemaField(name="alarmId")
    alarm_name = SchemaField(name="alarmName")
    fault_id = SchemaField(name="faultId")
    fault_name = SchemaField(name="faultName")

    def __init__(self, uuid, severity, alarm_id, alarm_name, fault_id, fault_name):
        super(Alarm, self).__init__()
        self.uuid = uuid
        self.severity = severity
        self.alarm_id = alarm_id
        self.alarm_name = alarm_name
        self.fault_id = fault_id
        self.fault_name = fault_name


class CpIfInterface(SchemaObject):
    link_type = SchemaField(name='linkType', not_null=True)
    link_status = SchemaField(name='linkStatus', not_null=True)
    local_ip_address = SchemaField(name='localIPAddress', optional=True)
    remote_ip_address = SchemaField(name='remoteIPAddress', optional=True)
    peer_ne = SchemaField(name='peerNE', optional=True)

    def __init__(self, link_type, link_status, local_ip_address, remote_ip_address, peer_ne):
        super(CpIfInterface, self).__init__()
        self.link_type = link_type
        self.link_status = link_status
        self.local_ip_address = local_ip_address
        self.remote_ip_address = remote_ip_address
        self.peer_ne = peer_ne


class GetVNFCSASMV1(SchemaObject):
    alarms = SchemaField(name="alarms", klass=Alarm, many=True)
    availability_status = SchemaField(name="availabilityStatus")
    dist_names = SchemaField(name="distNames")
    hostname = SchemaField(name="hostname")
    id = SchemaField(name="id", not_null=True)
    instance = SchemaField(name="instance", not_null=True)
    ip_interfaces = SchemaField(name="ipInterfaces")
    name = SchemaField(name="name")
    operational_state = SchemaField(name="operationalState")
    two_nactivity = SchemaField(name="twoNactivity", optional=True)
    role = SchemaField(name="role", optional=True)
    software_version = SchemaField(name="softwareVersion")
    links = SchemaField(name='links', optional=True, many=True, klass=CpIfInterface)

    def __init__(self, alarms, availability_status, dist_names, hostname, id, instance, ip_interfaces, name,
                 operational_state, two_nactivity, software_version, links, role):
        super(GetVNFCSASMV1, self).__init__()
        self.alarms = alarms
        self.availability_status = availability_status
        self.dist_names = dist_names
        self.hostname = hostname
        self.id = id
        self.instance = instance
        self.ip_interfaces = ip_interfaces
        self.name = name
        self.operational_state = operational_state
        self.two_nactivity = two_nactivity
        self.role = role
        self.software_version = software_version
        self.links = links
